#![cfg_attr(not(any(test, feature = "export-abi")), no_std)]
extern crate alloc;

use stylus_sdk::{
    alloy_primitives::{Address, U256},
    prelude::*,
    storage::{StorageMap, StorageU256},
};

// A reusable "component" with its own storage and public interface.
#[storage]
pub struct Erc20 {
    pub balances: StorageMap<Address, StorageU256>,
    pub total_supply: StorageU256,
}

// Accessor trait the user's entrypoint implements to expose the component.
pub trait HasErc20 {
    fn erc20(&self) -> &Erc20;
    fn erc20_mut(&mut self) -> &mut Erc20;
}

// Public trait whose methods have default bodies that delegate to the component.
#[public]
pub trait IErc20: HasErc20 {
    fn total_supply(&self) -> U256 {
        self.erc20().total_supply.get()
    }

    fn balance_of(&self, account: Address) -> U256 {
        self.erc20().balances.get(account)
    }
}

#[storage]
#[entrypoint]
pub struct Token {
    pub erc20: Erc20,
}

impl HasErc20 for Token {
    fn erc20(&self) -> &Erc20 {
        &self.erc20
    }
    fn erc20_mut(&mut self) -> &mut Erc20 {
        &mut self.erc20
    }
}

// No method bodies: everything routes to the defaults in `IErc20`.
#[public]
#[implements(IErc20)]
impl Token {}

#[public]
impl IErc20 for Token {}

#[cfg(test)]
mod tests {
    use super::*;
    use stylus_sdk::testing::*;

    #[test]
    fn default_bodies_read_component_state() {
        let vm = TestVM::default();
        let mut token = Token::from(&vm);
        let who = Address::repeat_byte(7);
        token.erc20.total_supply.set(U256::from(42));
        token.erc20.balances.setter(who).set(U256::from(5));
        assert_eq!(IErc20::total_supply(&token), U256::from(42));
        assert_eq!(IErc20::balance_of(&token, who), U256::from(5));
    }
}

