#!/usr/bin/perl
# Second pass of SDK 0.10 import fixes.
#  - `call::{...}` groups: `Call`/`StaticCallContext` come from the prelude; `MethodError`
#    moved to `stylus_sdk::stylus_core::calls::errors`.
#  - bare `stylus_core::` paths get the `stylus_sdk::` prefix.
#  - files using `#[public]` without the prelude import it explicitly.
# Usage: perl fix_sdk_imports2.pl FILE...
use strict;
use warnings;

for my $file (@ARGV) {
    open my $fh, '<', $file or die "open $file: $!";
    local $/;
    my $src = <$fh>;
    close $fh;
    my $orig = $src;
    my $needs_method = 0;

    $src =~ s{call::\{([^{}]*)\}}{
        my $group = $1;
        my @keep;
        for my $item (split /,/, $group) {
            (my $t = $item) =~ s/^\s+|\s+$//g;
            next if $t eq '';
            next if $t eq 'Call' || $t eq 'StaticCallContext';
            if ($t eq 'MethodError') { $needs_method = 1; next; }
            push @keep, $t;
        }
        if (!@keep) { ""; }
        elsif (@keep == 1 && $keep[0] eq 'self') { "call"; }
        else { "call::{" . join(', ', @keep) . "}"; }
    }gse;

    # Remove now-empty `use stylus_sdk::{ , }` artefacts.
    $src =~ s/,\s*,/,/g;
    $src =~ s/\{\s*,/{/g;
    $src =~ s/,\s*\}/}/g;

    $src =~ s/(?<![:\w])stylus_core::/stylus_sdk::stylus_core::/g;

    my $extra = "";
    $extra .= "use stylus_sdk::stylus_core::calls::errors::MethodError;\n" if $needs_method;
    if ($src =~ /#\[public\]/ && $src !~ /prelude::(\*|public)/) {
        $extra .= "use stylus_sdk::prelude::public;\n";
    }
    if ($extra ne "" && $src =~ /^use [^\n]*;\n/m) {
        $src =~ s/^(use [^\n]*;\n)/$1$extra/m;
    }

    if ($src ne $orig) {
        open my $out, '>', $file or die "write $file: $!";
        print $out $src;
        close $out;
        print "updated $file\n";
    }
}

