    sync::OnceLock,
\};
)/pub mod assert;

$1/m' lib/devnet/src/lib.rs && head -12 lib/devnet/src/lib.rs | tail -6 && (cargo +1.91.0 check -p devnet > /tmp/bench/logs/devnet-assert.log 2>&1; echo "EXIT=$?" >> /tmp/bench/logs/devnet-assert.log); grep -E '^(error|warning)' -A8 /tmp/bench/logs/devnet-assert.log | head -50 | cut -c1-200; tail -1 /tmp/bench/logs/devnet-assert.log

for f in .github/workflows/*.yml; do perl -0pi -e 's/cargo-stylus\@0\.6\.3/cargo-stylus\@0.10.10/g; s/cargo-stylus-0\.6\.3-/cargo-stylus-0.10.10-/g; s/      - name: Setup nitro node\n        run: \.\/scripts\/nitro-testnode\.sh -d -i\n\n//g; s/      - name: Setup nitro node\n        run: \.\/scripts\/nitro-testnode\.sh -d -i\n//g; s/# - Spin up `nitro-testnode`/# - Start the Stylus SDK devnet (done by scripts\/e2e-tests.sh)/g; s/toolchain: \[stable, beta\]/toolchain: [1.91.0]/g' "$f"; done && grep -rn 'nitro\|0\.6\.3\|stable, beta' .github/workflows/ | cut -c1-150; echo "--- e2e workflow tail ---"; tail -12 .github/workflows/e2e-tests.yml; echo "--- python yaml check ---"; python3 -c "
import sys,glob
try:
    import yaml
except ImportError:
    print('no pyyaml; skipping'); sys.exit(0)
for f in glob.glob('.github/workflows/*.yml'):
    yaml.safe_load(open(f))
print('all workflows parse')
"

